const zhRules=Object.entries(zhDisplay).sort((a,b)=>b[0].length-a[0].length);
const zhBuckets=new Map();for(const row of zhRules){const first=row[0][0];if(!zhBuckets.has(first))zhBuckets.set(first,[]);zhBuckets.get(first).push(row);}
function displayChinese(source){let output='';for(let i=0;i<source.length;){const row=zhBuckets.get(source[i])?.find(r=>source.startsWith(r[0],i));if(row){output+=row[1];i+=row[0].length;}else output+=source[i++];}return output;}

