const map=new Map(entries.map(row=>[row[0],row]));
const sorted=entries.slice().sort((a,b)=>b[0].length-a[0].length);
const buckets=new Map();for(const row of sorted){const first=row[0][0];if(!buckets.has(first))buckets.set(first,[]);buckets.get(first).push(row);}
export const catalog=entries;

export function tr(value){
 if(value===null||value===undefined)return '';const source=String(value);if(locale==='zh')return displayChinese(source);
 // Templates can contain model fields that are already in the chosen language.
 // Preserve them instead of translating shared Japanese kanji a second time.
 if(entries.some(row=>row[locale==='ja'?1:2]===source.trim()))return source;
 const direct=map.get(source.trim());if(direct)return source.replace(source.trim(),direct[locale==='ja'?1:2]);
 const language=locale==='ja'?1:2;
 let text=source;
 text=text.replace(/^驾驶 (.+) 出击 ↗$/,(_,ship)=>locale==='ja'?`${ship} で出撃 ↗`:`Launch with ${ship} ↗`);
 text=text.replace(/^已锁定 (.+)。保持航线。$/,(_,boss)=>locale==='ja'?`${boss} を捕捉。航路を保持。`:`Target locked: ${boss}. Hold your route.`);
 // Translate non-overlapping source segments once; never retranslate replacement text.
 let result='';for(let i=0;i<text.length;){const row=buckets.get(text[i])?.find(r=>text.startsWith(r[0],i));if(row){result+=row[language];i+=row[0].length;}else result+=text[i++];}
 return result;
}

export function canonicalText(value,from=locale){const text=String(value??'');if(from==='zh')return text;const index=from==='ja'?1:2;const direct=entries.find(row=>row[index]===text.trim());if(direct)return text.replace(text.trim(),direct[0]);const rules=entries.slice().sort((a,b)=>b[index].length-a[index].length);let result='';for(let i=0;i<text.length;){const row=rules.find(r=>text.startsWith(r[index],i));if(row){result+=row[0];i+=row[index].length;}else result+=text[i++];}return result;}

export function localizeHtml(html){return String(html).replace(/>([^<]*)</g,(_,text)=>'>'+tr(text)+'<').replace(/\b(alt|title|aria-label)="([^"]*)"/g,(_,name,text)=>`${name}="${tr(text).replaceAll('"','&quot;')}"`);}

export function setLocale(next){if(!LANGUAGES.some(l=>l.id===next))return false;locale=next;
 const localizeObject=(target,base,fields)=>{for(const field of fields){const value=base[field];target[field]=Array.isArray(value)?value.map(tr):tr(value);}};
 SHIPS.forEach((s,i)=>localizeObject(s,original.SHIPS[i],['name','role','skill','ultimate','passive','description','skillText','ultText']));
 CHAPTERS.forEach((c,i)=>localizeObject(c,original.CHAPTERS[i],['name','subtitle','boss','locations','stories','hazard']));
 ENEMIES.forEach((e,i)=>localizeObject(e,original.ENEMIES[i],['name','hint']));
 TALENTS.forEach((t,i)=>localizeObject(t,original.TALENTS[i],['name','note']));
 DIFFICULTIES.forEach((d,i)=>localizeObject(d,original.DIFFICULTIES[i],['name']));
 original.SKINS.forEach((s,i)=>SKINS[i]=tr(s));return true;
}

let staticTexts=null,staticAttributes=null;
export function applyStaticLocale(doc){
 if(!staticTexts){staticTexts=[];const walker=doc.createTreeWalker(doc.body,NodeFilter.SHOW_TEXT);let node;while((node=walker.nextNode())){if(node.parentElement?.closest?.('#language-screen,script,style'))continue;if(node.nodeValue.trim())staticTexts.push({node,source:node.nodeValue});}
  staticAttributes=[];for(const element of doc.querySelectorAll('[aria-label],[title],[alt]')){if(element.closest?.('#language-screen'))continue;for(const attr of ['aria-label','title','alt'])if(element.hasAttribute(attr))staticAttributes.push({element,attr,source:element.getAttribute(attr)});}}
 for(const item of staticTexts)item.node.nodeValue=tr(item.source);
 for(const item of staticAttributes)item.element.setAttribute(item.attr,tr(item.source));
 doc.documentElement.lang=LANGUAGES.find(l=>l.id===locale).html;doc.documentElement.dataset.locale=locale;doc.title=tr('裂空回响')+' · AERO ECHO';
}
